window.LENSES_PACK = {"commit":"3d592ece6de8c4559987416a544fc215fd6d6921","steps":[{"id":"rpc","path":"crates/rpc/rpc-eth-api/src/core.rs","file":"core.rs","start":920,"end":924,"sourceUrl":"https://github.com/paradigmxyz/reth/blob/3d592ece6de8c4559987416a544fc215fd6d6921/crates/rpc/rpc-eth-api/src/core.rs#L920-L924","contentHash":"bed3557bb9602e7337d6c7249cd3e0b53870c86f15ff7896dcf186b648322b9f","title":"RPC の入口を読む","question":"署名済みトランザクションは、どこへ渡る？","subtitle":"eth_sendRawTransaction のハンドラーから、共通ヘルパーへの委譲を追います。","symbol":"send_raw_transaction","node":"RPC の入口","short":"入口と委譲","lines":[921,923],"summary":"RPC ハンドラーは、共通のトランザクション処理へ委譲します。","detail":"受け取った Bytes を EthTransactions::send_raw_transaction に渡し、結果を待ちます。成功時は B256 のハッシュを RPC の結果として返します。","input":"署名済みトランザクションのバイト列（Bytes）","output":"RpcResult<B256>：成功時はハッシュ","side":"トレースログの記録、ヘルパーの呼び出し","branch":"await? で失敗を呼び出し元へ伝播します。成功はブロック取り込みの完了を意味しません。","concept":".await? と Ok(...)","language":"await で Future の結果を待ち、その Result に ? を適用します。Ok なら値を取り出し、Err なら必要な型変換を行って呼び出し元へ返します。","compare":"TypeScript の await に似ていますが、Result の Err は Promise の reject とは別の値です。? がエラーの早期返却を明示します。","doc":"https://doc.rust-lang.org/book/ch09-02-recoverable-errors-with-result.html","related":"rpc-contract","group":"RPC","edge":"ヘルパーへ委譲","edgeLine":923,"structureUrl":"zoom.html?area=rpc&c=interface&f=crates%2Frpc%2Frpc-eth-api%2Fsrc%2Fcore.rs"},{"id":"recover","path":"crates/rpc/rpc-eth-api/src/helpers/transaction.rs","file":"transaction.rs","start":81,"end":109,"sourceUrl":"https://github.com/paradigmxyz/reth/blob/3d592ece6de8c4559987416a544fc215fd6d6921/crates/rpc/rpc-eth-api/src/helpers/transaction.rs#L81-L109","contentHash":"d066febcf3cc92992a5addaa4c13654202cf6dd200054e0a4f9f37799aafe0ef","title":"デコードして送信者を復元","question":"バイト列は、どうプール用の型になる？","subtitle":"生のバイト列からプール用トランザクションを復元し、Local として次へ渡します。","symbol":"EthTransactions::send_raw_transaction","node":"デコード・送信者復元","short":"型と入力の確認","lines":[88,94],"summary":"復元に成功したトランザクションを、元のバイト列と組にして渡します。","detail":"recover_raw_pool_transaction はキャッシュ設定に応じた復元フックを選びます。次の send_pool_transaction には TransactionOrigin::Local を指定し、WithEncoded に元のバイト列と復元結果を持たせます。","input":"Bytes と &self","output":"Result<B256, Self::Error> を返す Future","side":"設定に応じた復元処理、送信処理への委譲","branch":"復元の失敗時は ? で早期終了し、send_pool_transaction を呼びません。キャッシュの有無で呼ぶ復元フックが変わります。","concept":"&tx / async move / impl Future","language":"&tx は値を借用します。async move は使う値を非同期ブロックへ取り込みます。戻り値の impl Future は具体的な型名を隠しつつ、Future を返すことを表します。","compare":"TypeScript の型注釈と異なり、Rust の借用は所有権に関わる制約です。Future は通常、ポーリングされて処理が進みます。","doc":"https://doc.rust-lang.org/book/ch17-01-futures-and-syntax.html","related":"recovery-hook","group":"DECODE","edge":"EthApi の実装へ","edgeLine":90,"structureUrl":"zoom.html?area=rpc&c=helpers&f=crates%2Frpc%2Frpc-eth-api%2Fsrc%2Fhelpers%2Ftransaction.rs"},{"id":"submit","path":"crates/rpc/rpc/src/eth/helpers/transaction.rs","file":"transaction.rs","start":32,"end":114,"sourceUrl":"https://github.com/paradigmxyz/reth/blob/3d592ece6de8c4559987416a544fc215fd6d6921/crates/rpc/rpc/src/eth/helpers/transaction.rs#L32-L114","contentHash":"866ae7cc641b85c2d06260abf471913d5741ef54e97838fe4f8f991c6ab7cd17","title":"通常の送信経路を追う","question":"どの条件で、ローカルのプールへ進む？","subtitle":"転送先なし・blob 変換対象外の経路に注目します。省略箇所は展開できます。","symbol":"EthApi::send_pool_transaction","node":"通常経路を選ぶ","short":"転送先の有無で分岐","lines":[107,113],"folds":[[39,86],[88,105]],"summary":"通常経路では購読者へ通知し、プールへの追加結果を待ちます。","detail":"WithEncoded を分解した後、設定次第で blob sidecar の変換や外部 RPC への転送に分岐します。ここでは転送先がない経路を読み、add_pool_transaction の成功結果から hash を取り出します。","input":"origin と WithEncoded<PoolTx<Self::Pool>>","output":"成功時はプール追加結果の hash","side":"raw transaction 購読者への通知、追加要求","branch":"転送先があれば別経路で早期 return します。通常経路の追加失敗は ? で返ります。購読者への通知を P2P 伝播の完了と混同しないでください。","concept":"構造体パターン { hash, .. }","language":"AddedTransactionOutcome { hash, .. } は構造体を分解して hash を取り出します。.. は残りのフィールドを指定しないことを表します。","compare":"TypeScript のオブジェクト分割代入に似ていますが、Rust ではフィールドの所有権や借用も考慮します。","doc":"https://doc.rust-lang.org/book/ch19-03-pattern-syntax.html","related":"forward","group":"BRANCH","edge":"追加要求を作る","edgeLine":111,"structureUrl":"zoom.html?area=rpc&c=implementation&f=crates%2Frpc%2Frpc%2Fsrc%2Feth%2Fhelpers%2Ftransaction.rs"},{"id":"queue","path":"crates/rpc/rpc/src/eth/core.rs","file":"core.rs","start":489,"end":504,"sourceUrl":"https://github.com/paradigmxyz/reth/blob/3d592ece6de8c4559987416a544fc215fd6d6921/crates/rpc/rpc/src/eth/core.rs#L489-L504","contentHash":"fd159467b7670555e1ab3e3663276a187ca277d261c29e6b27f1f7dbb37cd512","title":"追加要求をチャネルへ送る","question":"RPC は、プールへの追加をどう待つ？","subtitle":"要求を送るチャネルと、結果を一度だけ受け取るチャネルを分けて読みます。","symbol":"EthApiInner::add_pool_transaction","node":"要求と応答をつなぐ","short":"チャネルと二重の Result","lines":[496,503],"summary":"バッチ処理へ要求を送り、oneshot で個別の結果を待ちます。","detail":"response_tx を要求に添えて tx_batch_sender に送ります。RPC 側は response_rx を保持し、処理側から追加結果が戻るのを待ちます。このメソッド自身はトランザクションの検証を実行していません。","input":"未検証トランザクションと origin","output":"Result<AddedTransactionOutcome, EthApiError>","side":"バッチ処理の要求キューへの送信","branch":"send 失敗は BatchTxSendError。await?? の一つ目は受信失敗、二つ目は届いた追加結果の失敗を伝播します。","concept":"oneshot / .await??","language":"oneshot は一度だけ結果を送受信するチャネルです。ここで await の結果は Result の中に Result を持つため、? を二回適用してそれぞれの失敗を処理します。","compare":"Promise の resolve 用コールバックを渡す構成に似ていますが、送信側・受信側が明示的な型に分かれ、チャネル切断も結果として扱います。","doc":"https://docs.rs/tokio/latest/tokio/sync/oneshot/index.html","related":"batch-runner","group":"CHANNEL","edge":"チャネル経由で受信","edgeLine":500,"structureUrl":"zoom.html?area=rpc&c=implementation&f=crates%2Frpc%2Frpc%2Fsrc%2Feth%2Fcore.rs"},{"id":"batch","path":"crates/transaction-pool/src/batcher.rs","file":"batcher.rs","start":69,"end":105,"sourceUrl":"https://github.com/paradigmxyz/reth/blob/3d592ece6de8c4559987416a544fc215fd6d6921/crates/transaction-pool/src/batcher.rs#L69-L105","contentHash":"651fd1d5815a1733309eba00584f2a24807211cfcce73c75598fbe3738163262","title":"バッチをプールへ引き渡す","question":"要求はいつ、一件または複数件で処理される？","subtitle":"一件・同じ origin・異なる origin の三つの分岐を確認します。","symbol":"BatchTxProcessor::process_batch","node":"まとめて引き渡す","short":"一件とバッチの分岐","lines":[77,94],"summary":"要求の件数と origin に合わせて、プールの追加メソッドを選びます。","detail":"一件なら process_request → add_transaction、同じ origin の複数件なら add_transactions、混在時は add_transactions_with_origins を呼びます。各要求に添えられた response_tx に結果を戻します。","input":"Vec<BatchTxRequest<Pool::Transaction>>","output":"各要求の oneshot にプールの結果を返す","side":"検証・追加の委譲、応答チャネルへの送信","branch":"response_tx.send の結果は let _ で捨てています。受信側がなくても、この箇所ではエラーを上へ返しません。","concept":"into_iter / unzip / zip","language":"into_iter はコレクションを消費する反復を行います。ここで unzip はトランザクションと返信先を二つの Vec に分け、zip は各結果と返信先を順に組にします。","compare":"TypeScript の map で複数配列を作る考え方に近いですが、into_iter は元のコレクションの所有権を消費します。","doc":"https://doc.rust-lang.org/std/iter/trait.Iterator.html#method.unzip","related":"batch-runner","group":"BATCH","edge":"検証付き API へ","edgeLine":91,"structureUrl":"zoom.html?area=pool&c=1&f=crates%2Ftransaction-pool%2Fsrc%2Fbatcher.rs"},{"id":"pool","path":"crates/transaction-pool/src/lib.rs","file":"lib.rs","start":495,"end":528,"sourceUrl":"https://github.com/paradigmxyz/reth/blob/3d592ece6de8c4559987416a544fc215fd6d6921/crates/transaction-pool/src/lib.rs#L495-L528","contentHash":"87582b4a22dc8ac527f8380847cec7d6dcc133c0e12ff281034d3a6252df1443","title":"検証してプールに追加","question":"成功したら、すでにチェーンへ記録された？","subtitle":"プールへの追加と、ブロックへの取り込みを区別して読解を締めくくります。","symbol":"Pool::add_transaction","node":"検証・プール追加","short":"ハッシュと確定の違い","lines":[495,502],"folds":[[518,527]],"summary":"検証結果を内部プールへ渡し、追加の成否を返します。","detail":"単件・複数件ともに検証を経由して内部プールへ渡します。単件では結果リストから一件を取り出します。この経路はレシートやブロック取り込みを待つ処理ではありません。","input":"未検証トランザクションと origin","output":"PoolResult<AddedTransactionOutcome>","side":"検証処理、内部プールの更新","branch":"検証結果を内部プールが扱い、追加結果を返します。結果リストが空なら expect は panic します。検証器の具体的な条件はこの抜粋の外です。","concept":"Self::Transaction / expect","language":"Self::Transaction は、この実装が使う関連型です。expect は値が存在すれば取り出し、存在しなければ指定メッセージで panic します。? によるエラー伝播とは挙動が違います。","compare":"TypeScript の非 null アサーション ! は実行時検証をしません。Rust の expect は実行時に失敗を検出し、panic します。","doc":"https://doc.rust-lang.org/book/ch09-02-recoverable-errors-with-result.html","related":"pool-test","group":"POOL","edge":"","edgeLine":500,"structureUrl":"zoom.html?area=pool&c=1&f=crates%2Ftransaction-pool%2Fsrc%2Flib.rs"}]};